/// The private index, in the project's data.
const INDEX: &str = ".suspense/snapshot-index";

/// The repository `project_dir` is in, by its top directory; none if it
/// isn't in one, and then nothing is snapshotted.
pub fn repo_top(project_dir: &Path) -> Option<PathBuf> {
    let output = crate::process::command("git")
        .args(["rev-parse", "--show-toplevel"])
        .current_dir(project_dir)
        .output_logged()
        .ok()?;
    if !output.status.success() {
        return None;
    }
    let top = String::from_utf8(output.stdout).ok()?;
    Some(PathBuf::from(top.trim_end_matches(['\n', '\r'])))
}

/// Git, run in `top` against the private index of `project_dir`.
fn git(top: &Path, project_dir: &Path) -> Command {
    let mut command = crate::process::command("git");
    command
        .current_dir(top)
        .env("GIT_INDEX_FILE", project_dir.join(INDEX));
    command
}

fn run(mut command: Command, what: &str) -> Result<String> {
    let output = command
        .output_logged()
        .with_context(|| format!("could not run git to {what}"))?;
    if !output.status.success() {
        bail!(
            "git could not {what}: {}",
            String::from_utf8_lossy(&output.stderr).trim()
        );
    }
    Ok(String::from_utf8_lossy(&output.stdout).into_owned())
}

/// Snapshots the working tree of the repository `project_dir` is in, as git
/// sees it, `.gitignore` followed, and pins the tree under
/// `refs/suspense/<task>/<which>`. Returns the tree's hash.
pub fn take(project_dir: &Path, task: &str, which: &str) -> Result<String> {
    let top = repo_top(project_dir).context("the project isn't a git repository")?;
    std::fs::create_dir_all(project_dir.join(".suspense")).context("could not create .suspense")?;
    // The private index is never in the snapshot, whether or not the
    // project's .gitignore says so. Named when git already ignores it, git
    // would refuse, so it is excluded only when it isn't.
    let index = project_dir.join(INDEX);
    let ignored = crate::process::command("git")
        .current_dir(&top)
        .args(["check-ignore", "-q", "--no-index"])
        .arg(&index)
        .status_logged()
        .is_ok_and(|status| status.success());
    let index = index.strip_prefix(&top).unwrap_or(&index);
    let mut add = git(&top, project_dir);
    add.args(["add", "-A", "--", ":/"]);
    if !ignored {
        add.arg(format!(":(top,exclude){}", index.display()))
            .arg(format!(":(top,exclude){}.lock", index.display()));
    }
    run(add, "snapshot the working tree")?;
    let mut write = git(&top, project_dir);
    write.arg("write-tree");
    let tree = run(write, "write the snapshot's tree")?.trim().to_string();
    let mut pin = crate::process::command("git");
    pin.current_dir(&top).args([
        "update-ref",
        &format!("refs/suspense/{task}/{which}"),
        &tree,
    ]);
    run(pin, "keep the snapshot")?;
    Ok(tree)
}

/// How a file changed between two snapshots.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ChangeKind {
    Added,
    Modified,
    Deleted,
    Renamed,
}

impl ChangeKind {
    pub fn letter(self) -> &'static str {
        match self {
            ChangeKind::Added => "A",
            ChangeKind::Modified => "M",
            ChangeKind::Deleted => "D",
            ChangeKind::Renamed => "R",
        }
    }
}

/// A file that changed between two snapshots, by its path from the
/// repository's top.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Change {
    pub kind: ChangeKind,
    pub path: PathBuf,
    /// Where a renamed file was before.
    pub from: Option<PathBuf>,
}

/// The files that changed between the trees `before` and `after`, in path
/// order, as `git diff --name-status` gives them.
pub fn changes(top: &Path, before: &str, after: &str) -> Result<Vec<Change>> {
    let mut diff = crate::process::command("git");
    diff.current_dir(top)
        .args(["diff", "--name-status", "-z", "-M", before, after]);
    let mut changes = parse(&run(diff, "list the changed files")?);
    changes.sort_by(|a, b| a.path.cmp(&b.path));
    Ok(changes)
}

/// Whether `path` is something the application keeps for itself rather than
/// one of the project's own files: anything in a `.suspense` directory, or
/// the draft, `.suspense-draft.pi`, wherever it is.
pub fn is_application_data(path: &Path) -> bool {
    path.file_name()
        .is_some_and(|name| name == ".suspense-draft.pi")
        || path
            .components()
            .any(|part| part.as_os_str() == ".suspense")
}

/// `changes` with what the application keeps for itself left out: a file
/// renamed into it is listed as deleted from where it was, one renamed out of
/// it as added where it is now.
pub fn project_own(changes: Vec<Change>) -> Vec<Change> {
    changes
        .into_iter()
        .filter_map(|change| {
            let from_kept = change.from.as_deref().map(is_application_data);
            match (is_application_data(&change.path), from_kept) {
                (true, Some(false)) => Some(Change {
                    kind: ChangeKind::Deleted,
                    path: change.from?,
                    from: None,
                }),
                (true, _) => None,
                (false, Some(true)) => Some(Change {
                    kind: ChangeKind::Added,
                    path: change.path,
                    from: None,
                }),
                (false, _) => Some(change),
            }
        })
        .collect()
}

/// Reads `git diff --name-status -z`: each status, then its path, or for a
/// rename or copy its old path and its new.
fn parse(output: &str) -> Vec<Change> {
    let mut fields = output.split('\0').filter(|field| !field.is_empty());
    let mut changes = Vec::new();
    while let Some(status) = fields.next() {
        let kind = match status.chars().next() {
            Some('A') | Some('C') => ChangeKind::Added,
            Some('D') => ChangeKind::Deleted,
            Some('R') => ChangeKind::Renamed,
            _ => ChangeKind::Modified,
        };
        let copied = status.starts_with('C');
        let (from, path) = if kind == ChangeKind::Renamed || copied {
            let (Some(from), Some(to)) = (fields.next(), fields.next()) else {
                break;
            };
            ((!copied).then(|| PathBuf::from(from)), to)
        } else {
            let Some(path) = fields.next() else {
                break;
            };
            (None, path)
        };
        changes.push(Change {
            kind,
            path: PathBuf::from(path),
            from,
        });
    }
    changes
}

/// The contents of `path`, from the repository's top, in the tree `tree`;
/// none where it isn't in it.
pub fn contents(top: &Path, tree: &str, path: &Path) -> Option<Vec<u8>> {
}

/// The statuses of a repository's changed and ignored paths.
#[derive(Debug, Default, PartialEq)]
pub struct GitStatus {
    /// Files and folders `git status` names, by absolute path.
    paths: HashMap<PathBuf, Status>,
    /// Folders holding a changed file, with the most pressing status of what
    /// they hold.
    folders: HashMap<PathBuf, Status>,
    /// Ignored folders, whose contents are all ignored.
    ignored_folders: Vec<PathBuf>,
}

impl GitStatus {
    /// The status of the repository `project_dir` is in, or `None` outside of
    /// one or without git.
    pub fn read(project_dir: &Path) -> Option<Self> {
        let timed = crate::debug_log::Timed::begin(Some(project_dir), "git status refresh");
        let read = Self::read_untimed(project_dir);
        timed.end(match &read {
            Some(status) => format!("{} paths", status.paths.len()),
            None => "not a repository".into(),
        });
        read
    }

    fn read_untimed(project_dir: &Path) -> Option<Self> {
        // The repository's top, reached from the project directory as given
        // (`../..`), so paths match the tree's even through a symlink.
        let up = crate::process::command("git")
            .args(["rev-parse", "--show-cdup"])
            .current_dir(project_dir)
            .output_logged()
            .ok()
            .filter(|output| output.status.success())?;
        let mut top = project_dir.to_path_buf();
        for _ in String::from_utf8_lossy(&up.stdout)
            .trim()
            .split('/')
            .filter(|part| *part == "..")
        {
            top.pop();
        }
        let output = crate::process::command("git")
            .args([
                "status",
                "--porcelain=v1",
                "-z",
                "--untracked-files=all",
                "--ignored=matching",
            ])
            .current_dir(project_dir)
            .output_logged()
            .ok()
            .filter(|output| output.status.success())?;
        Some(Self::parse(&top, &output.stdout))
    }

    /// Reads `git status --porcelain=v1 -z` output, whose paths are relative
    /// to the repository's `top`.
    pub fn parse(top: &Path, output: &[u8]) -> Self {
        let mut status = Self::default();
        let mut records = output.split(|byte| *byte == 0);
        while let Some(record) = records.next() {
            if record.len() < 4 {
                continue;
            }
            let (x, y) = (record[0], record[1]);
            let path = String::from_utf8_lossy(&record[3..]);
            // A rename or copy is followed by the path it came from.
            if matches!(x, b'R' | b'C') {
                records.next();
            }
            let kind = match (x, y) {
                (b'!', b'!') => Status::Ignored,
                (b'?', b'?') => Status::Untracked,
                (b'D', b'D') | (b'A', b'A') | (b'U', _) | (_, b'U') => Status::Conflicted,
                (b'A', _) => Status::Added,
                _ => Status::Modified,
            };
            let is_folder = path.ends_with('/');
            let absolute = top.join(path.trim_end_matches('/'));
            if kind == Status::Ignored {
                if is_folder {
                    status.ignored_folders.push(absolute.clone());
                }
            } else {
                for folder in absolute.ancestors().skip(1) {
                    if !folder.starts_with(top) {
                        break;
                    }
                    let entry = status.folders.entry(folder.to_path_buf()).or_insert(kind);
                    *entry = (*entry).max(kind);
                }
            }
            status.paths.insert(absolute, kind);
        }
        status
    }

    /// The status `path` shows in the tree: its own, the most pressing among
    /// what a folder holds, or ignored inside an ignored folder. Unchanged
    /// paths have none.
    pub fn of(&self, path: &Path, is_folder: bool) -> Option<Status> {
        if self
            .ignored_folders
            .iter()
            .any(|folder| path.starts_with(folder))
        {
            return Some(Status::Ignored);
        }
        if is_folder {
            let held = self.folders.get(path).copied();
            return match (self.paths.get(path).copied(), held) {
                (Some(own), Some(held)) => Some(own.max(held)),
                (own, held) => own.or(held),
            };
        }
        self.paths.get(path).copied()
    }
}

#[cfg(test)]
mod tests {
    use std::path::Path;

    use super::{GitStatus, Status};

    /// Each kind of change reads back with its status, and a folder takes the
    /// most pressing of what it holds; ignored folders' contents are ignored.
    #[test]
    fn statuses_and_folders_read_back() {
        let top = Path::new("/repo");
        let output = [
            " M src/main.rs",
            "A  src/new.rs",
            "?? notes/draft.md",
            "UU src/deep/clash.rs",
            "R  src/renamed.rs",
            "src/old.rs",
            "!! target/",
            "!! debug.log",
        ]
        .join("\0");
        let status = GitStatus::parse(top, output.as_bytes());
        let of = |path: &str, folder| status.of(&top.join(path), folder);

        assert_eq!(of("src/main.rs", false), Some(Status::Modified));
        assert_eq!(of("src/new.rs", false), Some(Status::Added));
        assert_eq!(of("notes/draft.md", false), Some(Status::Untracked));
        assert_eq!(of("src/deep/clash.rs", false), Some(Status::Conflicted));
        assert_eq!(of("src/renamed.rs", false), Some(Status::Modified));
        assert_eq!(
            of("src/old.rs", false),
            None,
            "a rename's old path was read as a change"
        );
        assert_eq!(of("src/unchanged.rs", false), None);

        assert_eq!(of("src", true), Some(Status::Conflicted));
        assert_eq!(of("src/deep", true), Some(Status::Conflicted));
        assert_eq!(of("notes", true), Some(Status::Untracked));
        assert_eq!(of("docs", true), None);

        assert_eq!(of("target", true), Some(Status::Ignored));
        assert_eq!(of("target/debug/app", false), Some(Status::Ignored));
        assert_eq!(of("debug.log", false), Some(Status::Ignored));
    }

    /// In a real repository: a changed file, a new untracked one, and an
    /// ignored folder read back with their statuses, and the folders holding
    /// them take the most pressing. A folder outside any repository has none.
    #[test]
    fn reads_a_real_repository() {
        let dir = std::env::temp_dir().join(format!("suspense-git-{}", std::process::id()));
        std::fs::remove_dir_all(&dir).ok();
        std::fs::create_dir_all(dir.join("src")).unwrap();
        let git = |args: &[&str]| {
            let ok = crate::process::command("git")
                .args(["-c", "user.name=Test", "-c", "user.email=test@example.com"])
                .args(args)
                .current_dir(&dir)
                .output()
                .unwrap()
                .status
                .success();
            assert!(ok, "git {args:?} failed");
        };
        git(&["init", "-q"]);
        git(&["config", "core.autocrlf", "false"]);
        std::fs::write(dir.join("src/main.rs"), "fn main() {}\n").unwrap();
        std::fs::write(dir.join(".gitignore"), "build/\n").unwrap();
        git(&["add", "."]);
        git(&["commit", "-q", "-m", "first"]);
        std::fs::write(dir.join("src/main.rs"), "fn main() { changed() }\n").unwrap();
        std::fs::write(dir.join("notes.md"), "new\n").unwrap();
        std::fs::create_dir_all(dir.join("build")).unwrap();
        std::fs::write(dir.join("build/out"), "x").unwrap();

        let status = GitStatus::read(&dir.join("src")).expect("no status in a repository");
        let of = |path: &str, folder| status.of(&dir.join(path), folder);
        assert_eq!(of("src/main.rs", false), Some(Status::Modified));
        assert_eq!(of("src", true), Some(Status::Modified));
        assert_eq!(of("notes.md", false), Some(Status::Untracked));

